pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, n: i32) -> i32 {
    // Treat N as a length; per problem statement N is non-negative and both arrays have length N.
    // We'll iterate using usize for indexing.
    let n_usize = n as usize;

    debug_assert!(n >= 0, "N must be non-negative");
    debug_assert!(a.len() == n_usize, "a must have length N");
    debug_assert!(b.len() == n_usize, "b must have length N");

    let mut sum: i32 = 0;

    for i in 0..n_usize {
        let ii = i as i32;
        let bi = b[i];

        // Given the constraint: b[i] is either i or i+1.
        // Set a[i] to 1 if b[i] == i, else to 2 (so b[i] == i+1).
        let val = if bi == ii { 1 } else { 2 };

        a[i] = val;
        sum += val;
    }

    // Per statement: sum is guaranteed in [N, 2*N].
    sum
}